#!/bin/sh
# scripts_version: 23
# (the stamp above is the same in status.sh, task.sh and map.sh and goes up when any of them changes)
# Live state of the plan's tasks, read from each file's header. The text output follows the
# plan.json language (strings from core/i18n embedded below); --json and --options do not change.
# Usage: sh <plan-dir>/status.sh [filter] [--all] [--options] [--json]
#   filter     ID prefix (F1, F2-03) or track name (images, api…)
#   --all      also lists done, cancelled and abandoned tasks and drafts
#   --options  only the tasks that can start now, as TSV, from most to least
#              recommended: id, group (available|owner), unblocks, type, title
#   --json     the same computation as a JSON object (contract 1): language, profile and
#              scripts_version (from plan.json and the stamp), progress, phases, tasks,
#              parallel and run; the filter applies, --all changes nothing
#   --help, -h prints this usage (from the strings below) and exits 0, whatever else is given
#   any other argument that starts with -- is refused (exit 1), so a mistyped option is not a filter

cd "$(dirname "$0")" || exit 1
name=$(basename "$(pwd)")
script=$(basename "$0")

# Language and profile from plan.json (pt-BR and full when missing); scripts version from this file's stamp.
# >>> plan-field: generated by tools/script-strings.sh from core/template/plan-field.awk; do not edit by hand
# shellcheck disable=SC2016 # an awk program: the $ are awk fields
PLAN_FIELD_AWK='
# A text field of plan.json, read as the contract says (core/contract/contract.md, "plan.json"): only
# a key of the top-level object counts, not one nested in another value nor one quoted inside a
# string; the last one wins; a value that is not a string, or has a backslash, gives nothing. The
# single source: tools/script-strings.sh embeds this file in status.sh, task.sh and map.sh as the
# variable PLAN_FIELD_AWK, between the lines "# >>> plan-field" and "# <<< plan-field", and they run
#   awk -v field=<key> "$PLAN_FIELD_AWK" plan.json
# which prints the value, without a line break, or nothing. The reader in core/reader
# (planField in status.ts) scans the same way. No single quotes in this file, since it goes inside a
# single-quoted sh string.
{ s = s $0 "\n" }
END {
  n = length(s); depth = 0; top = 0; state = "key"; key = ""; found = ""
  for (i = 1; i <= n; i++) {
    c = substr(s, i, 1)
    if (c == "\"") {
      j = i + 1; escaped = 0
      while (j <= n && substr(s, j, 1) != "\"") {
        if (substr(s, j, 1) == "\\") { escaped = 1; j++ }
        j++
      }
      text = substr(s, i + 1, j - i - 1)
      i = j
      if (depth != 1 || !top) continue
      if (state == "key") { key = text; state = "colon" }
      else if (state == "value") { if (key == field) found = escaped ? "" : text; state = "comma" }
    } else if (c == "{" || c == "[") {
      if (depth == 1 && state == "value") { if (key == field) found = ""; state = "comma" }
      depth++
      if (depth == 1) { top = (c == "{"); state = "key" }
    } else if (c == "}" || c == "]") {
      depth--
    } else if (depth == 1 && top) {
      if (c == ":" && state == "colon") state = "value"
      else if (c == ",") state = "key"
      else if (state == "value" && c !~ /[ \t\r\n]/) { if (key == field) found = ""; state = "comma" }
    }
  }
  printf "%s", found
}
'
# <<< plan-field
plan_field() {
  [ -f plan.json ] || return 0
  awk -v field="$1" "$PLAN_FIELD_AWK" plan.json
}
language=$(plan_field language)
[ -n "$language" ] || language=pt-BR
profile=$(plan_field profile)
[ -n "$profile" ] || profile=full
version=$(sed -n 's/^# scripts_version: \([0-9][0-9]*\)$/\1/p' "$script" | head -1)
[ -n "$version" ] || version=null

# >>> strings (area status.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='status.noTasks	x-test:status.noTasks {0}
status.progress	x-test:status.progress {0} {1} {2} {3} {4}
status.phaseInProgress	x-test:status.phaseInProgress {0}
status.inProgress	x-test:status.inProgress {0}
status.ago	x-test:status.ago {0} {1}
status.durationDH	x-test:status.durationDH {0} {1}
status.durationHMin	x-test:status.durationHMin {0} {1}
status.durationMin	x-test:status.durationMin {0}
status.noStarted	x-test:status.noStarted
status.nextStep	x-test:status.nextStep {0}
status.available	x-test:status.available {0}
status.reposUnblocks	x-test:status.reposUnblocks {0} {1}
status.owner	x-test:status.owner {0}
status.unblocks	x-test:status.unblocks {0}
status.parallel	x-test:status.parallel
status.session	x-test:status.session {0} {1}
status.later	x-test:status.later {0} {1}
status.waiting	x-test:status.waiting {0}
status.waitsOn	x-test:status.waitsOn {0}
status.noNextStep	x-test:status.noNextStep {0}
status.unknownTier	x-test:status.unknownTier {0}
status.invalidStatus	x-test:status.invalidStatus {0}
status.duplicateId	x-test:status.duplicateId {0}
status.drafts	x-test:status.drafts {0}
status.done	x-test:status.done {0}
status.cancelled	x-test:status.cancelled {0}
status.abandoned	x-test:status.abandoned {0}
status.phaseAbandoned	x-test:status.phaseAbandoned
status.legend	x-test:status.legend
status.unknownOption	x-test:status.unknownOption {0}
status.usage	x-test:status.usage {0}
status.helpFilter	x-test:status.helpFilter
status.helpAll	x-test:status.helpAll
status.helpOptions	x-test:status.helpOptions
status.helpJson	x-test:status.helpJson
' ;;
  pt-BR) MSG_TABLE='status.noTasks	Nenhuma task encontrada em {0}/phase-*/
status.progress	PROGRESSO: {0} de {1} concluídas ({2}%) · {3} em andamento · {4} em rascunho
status.phaseInProgress	({0} em andamento)
status.inProgress	EM ANDAMENTO ({0})
status.ago	há {0} (desde {1})
status.durationDH	{0} d {1} h
status.durationHMin	{0} h {1} min
status.durationMin	{0} min
status.noStarted	sem Started:
status.nextStep	próximo passo: {0}
status.available	LIVRES PARA UMA SESSÃO ({0})
status.reposUnblocks	repos {0} · desbloqueia {1}
status.owner	LIVRES, PRECISAM DO DONO ({0})  — decision ou human
status.unblocks	desbloqueia {0}
status.parallel	SESSÕES PARALELAS SUGERIDAS — sem repos em comum entre si nem com as em andamento
status.session	sessão {0}: {1}
status.later	depois:   {0}  (repos ocupados: {1})
status.waiting	AGUARDANDO BLOQUEIOS ({0})
status.waitsOn	← espera {0}
status.noNextStep	EM ANDAMENTO SEM «Next step:» NO REGISTRO ({0}) — a sessão seguinte não sabe onde retomar
status.unknownTier	TIER DESCONHECIDO ({0}) — vale senior; os valores são junior, mid ou senior
status.invalidStatus	ESTADO INVÁLIDO OU AUSENTE ({0}) — a 1.ª linha deve ser Status: ready|draft|in-progress|done|cancelled|abandoned
status.duplicateId	ID REPETIDO ({0}) — mais de um arquivo com o mesmo ID; renomeie até sobrar um arquivo por ID
status.drafts	RASCUNHOS ({0}) — detalhados pela avaliação de fecho da fase anterior
status.done	CONCLUÍDAS ({0})
status.cancelled	CANCELADAS ({0})
status.abandoned	ABANDONADAS ({0}) — o dono desistiu; sh task.sh reopen <raiz> traz o grupo de volta
status.phaseAbandoned	(abandonada)
status.legend	(?) = ID citado em Blocked by que não existe como arquivo
status.unknownOption	Opção desconhecida: {0}. As opções são --all, --options e --json.
status.usage	Uso: sh {0}/status.sh [filtro] [--all] [--options] [--json]
status.helpFilter	  filtro     prefixo de ID de task ou nome de trilha; vale o último
status.helpAll	  --all      lista também as tasks feitas, canceladas, abandonadas e os rascunhos
status.helpOptions	  --options  só as tasks que podem começar agora, em TSV, da mais recomendada à menos
status.helpJson	  --json     o mesmo estado num objeto JSON, para máquinas
' ;;
  *) MSG_TABLE='status.noTasks	No task found in {0}/phase-*/
status.progress	PROGRESS: {0} of {1} done ({2}%) · {3} in progress · {4} in draft
status.phaseInProgress	({0} in progress)
status.inProgress	IN PROGRESS ({0})
status.ago	{0} ago (since {1})
status.durationDH	{0} d {1} h
status.durationHMin	{0} h {1} min
status.durationMin	{0} min
status.noStarted	no Started:
status.nextStep	next step: {0}
status.available	AVAILABLE FOR A SESSION ({0})
status.reposUnblocks	repos {0} · unblocks {1}
status.owner	AVAILABLE, NEED THE OWNER ({0})  — decision or human
status.unblocks	unblocks {0}
status.parallel	SUGGESTED PARALLEL SESSIONS — no repos in common with each other or with those in progress
status.session	session {0}: {1}
status.later	then:     {0}  (busy repos: {1})
status.waiting	WAITING ON BLOCKERS ({0})
status.waitsOn	← waits {0}
status.noNextStep	IN PROGRESS WITHOUT "Next step:" IN THE LOG ({0}) — the next session does not know where to resume
status.unknownTier	UNKNOWN TIER ({0}) — treated as senior; the values are junior, mid or senior
status.invalidStatus	INVALID OR MISSING STATE ({0}) — the 1st line must be Status: ready|draft|in-progress|done|cancelled|abandoned
status.duplicateId	DUPLICATED ID ({0}) — more than one file with the same ID; rename them until each ID has one file
status.drafts	DRAFTS ({0}) — detailed by the previous phase'\''s closing review
status.done	DONE ({0})
status.cancelled	CANCELLED ({0})
status.abandoned	ABANDONED ({0}) — the owner gave up; sh task.sh reopen <root> brings the group back
status.phaseAbandoned	(abandoned)
status.legend	(?) = ID cited in Blocked by that does not exist as a file
status.unknownOption	Unknown option: {0}. The options are --all, --options and --json.
status.usage	Usage: sh {0}/status.sh [filter] [--all] [--options] [--json]
status.helpFilter	  filter     a task ID prefix or a track name; the last one counts
status.helpAll	  --all      also lists done, cancelled and abandoned tasks and drafts
status.helpOptions	  --options  only the tasks that can start now, as TSV, most recommended first
status.helpJson	  --json     the same state as one JSON object, for machines
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings
# >>> header: generated by tools/script-strings.sh from core/template/header.awk; do not edit by hand
# shellcheck disable=SC2016 # an awk program: the $ are awk fields
HEADER_AWK='
# The task header, read and rewritten as the contract says (core/contract/contract.md, "Task header"
# and "What the verbs write"). The single source: tools/script-strings.sh embeds this file in
# status.sh, task.sh, map.sh and core/scripts/boundary.sh as the variable HEADER_AWK, between the
# lines "# >>> header" and "# <<< header", and each awk program of theirs starts with "$HEADER_AWK".
# Only functions: the program that embeds them calls them. No single quotes in this file, since it
# goes inside a single-quoted sh string.
#
# Reading. On the first line of each file, id = hdr_begin() (the key of the file: its id, from the
# file name; hdr_phase gets the folder). Then, on each line, hdr_line(id) returns 1 while the line
# belongs to the header, title line included, and 0 after it; so a program reads the header with the rule
#   hdr_line(id) { next }
# hdr_line first takes one CR off the end of the line, header or body, so a task saved with CRLF reads
# like one saved with LF; a program that calls it on every line sees $0 without the CR.
# The values go to these arrays, by key: state, type, track, tier, repos, blockers, started, finished,
# replaced, gave_up, fell_with, prev_state, title. Any key can be on any header line, Status: too; a
# repeated key keeps its last value. Repos: and Blocked by: lose their spaces and tabs; the title
# loses a leading "<ID> - " or "<ID> — ". hdr_get(id, name) gives the array of that name.
# An id that more than one file has (a duplicated id) gets a key per file: the id for the first file
# read, "<ID>#2", "<ID>#3"… for the next ones; hdr_dup[<ID>] is set and hdr_idof(key) gives the id back.
# The files come in plan order, so the key that is the bare id is the first file of the plan.

function hdr_begin(   n) {
  n = split(FILENAME, hdr_parts, "/")
  hdr_phase = hdr_parts[1]
  hdr_id = hdr_parts[n]
  if (match(hdr_id, /^F[0-9]+-[0-9]+(\.[0-9]+)*/)) hdr_id = substr(hdr_id, RSTART, RLENGTH)
  hdr_on = 1
  if (hdr_id in hdr_seen) { hdr_dup[hdr_id] = 1; return hdr_id "#" (++hdr_seen[hdr_id]) }
  hdr_seen[hdr_id] = 1
  return hdr_id
}

function hdr_idof(key) { sub(/#.*/, "", key); return key }

function hdr_line(id,   k, v) {
  sub(/\r$/, "")
  if (!hdr_on) return 0
  if ($0 ~ /^# /) {
    v = substr($0, 3)
    sub(/^F[0-9]+-[0-9]+(\.[0-9]+)*[ \t]*(—|-)[ \t]*/, "", v)
    title[id] = v
    hdr_on = 0
    return 1
  }
  k = $0
  if (!sub(/:.*/, "", k)) return 1
  v = substr($0, length(k) + 2)
  sub(/^[ \t]*/, "", v)
  if (k == "Status") state[id] = v
  else if (k == "Type") type[id] = v
  else if (k == "Track") track[id] = v
  else if (k == "Tier") tier[id] = v
  else if (k == "Repos") { gsub(/[ \t]/, "", v); repos[id] = v }
  else if (k == "Blocked by") { gsub(/[ \t]/, "", v); blockers[id] = v }
  else if (k == "Started") started[id] = v
  else if (k == "Finished") finished[id] = v
  else if (k == "Replaced by") replaced[id] = v
  else if (k == "Given up by") gave_up[id] = v
  else if (k == "Given up with") fell_with[id] = v
  else if (k == "Previous status") prev_state[id] = v
  return 1
}

function hdr_get(id, name) {
  if (name == "state") return state[id]
  if (name == "type") return type[id]
  if (name == "track") return track[id]
  if (name == "tier") return tier[id]
  if (name == "repos") return repos[id]
  if (name == "blockers") return blockers[id]
  if (name == "started") return started[id]
  if (name == "finished") return finished[id]
  if (name == "replaced") return replaced[id]
  if (name == "gave_up") return gave_up[id]
  if (name == "fell_with") return fell_with[id]
  if (name == "prev_state") return prev_state[id]
  if (name == "title") return title[id]
  return ""
}

# Writing. hdr_write(fname, tmp, st, ins, drop, entry) writes to tmp the text of fname with the
# header rewritten: the Status: line (the last one, the one the reader keeps) becomes "Status: st",
# on the line where it was, and the lines of ins (separated by line breaks; none when empty) go right
# after it; every other header line whose start matches the regular expression drop goes away; every
# other line, blank lines included, stays where it was. With entry not empty, the line "- entry" goes
# into the "## Log" section (the first line equal to "## Log" below the title, or anywhere in a file
# without a title, up to the next line
# that starts with "# " or "## "): right after its last non-blank line or, with the section empty,
# after "## Log" and a blank line; without the section, the blank lines at the end go away and a
# blank line, "## Log", a blank line and the entry are added.
# Lines are compared without a CR at the end, and the whole file is written with the line ending of
# its first line: a task saved with CRLF stays CRLF, new lines included.
function hdr_write(fname, tmp, st, ins, drop, entry,   n, l, i, j, t, sl, s, e, p, z, ni, lines, eol) {
  n = 0; eol = "\n"
  while ((getline l < fname) > 0) {
    if (n == 0 && l ~ /\r$/) eol = "\r\n"
    sub(/\r$/, "", l); hdr_text[++n] = l
  }
  close(fname)
  t = n + 1; for (i = 1; i <= n; i++) if (hdr_text[i] ~ /^# /) { t = i; break }
  sl = 0; for (i = 1; i < t; i++) if (hdr_text[i] ~ /^Status:/) sl = i
  s = 0; p = 0; z = n
  if (entry != "") {
    for (i = (t <= n ? t + 1 : 1); i <= n; i++) if (hdr_text[i] == "## Log") { s = i; break }
    if (s) {
      e = n + 1; for (i = s + 1; i <= n; i++) if (hdr_text[i] ~ /^(# |## )/) { e = i; break }
      p = s; for (i = s + 1; i < e; i++) if (hdr_text[i] !~ /^[ \t]*$/) p = i
    } else while (z > 1 && hdr_text[z] ~ /^[ \t]*$/) z--
  }
  ni = split(ins, lines, "\n")
  for (i = 1; i <= z; i++) {
    if (i == sl || (sl == 0 && i == 1)) {
      printf "Status: %s%s", st, eol > tmp
      for (j = 1; j <= ni; j++) if (lines[j] != "") printf "%s%s", lines[j], eol > tmp
      if (i == sl) continue
    }
    if (i < t && drop != "" && hdr_text[i] ~ drop) continue
    printf "%s%s", hdr_text[i], eol > tmp
    if (s && i == p) { if (p == s) printf "%s", eol > tmp; printf "- %s%s", entry, eol > tmp }
  }
  if (entry != "" && !s) printf "%s## Log%s%s- %s%s", eol, eol, eol, entry, eol > tmp
  close(tmp)
}
'
# <<< header

filter=""
all=0
options=0
json=0
help=0
unknown=""
for arg in "$@"; do
  case "$arg" in
    --all) all=1 ;;
    --options) options=1 ;;
    --json) json=1 ;;
    --help|-h) help=1 ;;
    --*) if [ -z "$unknown" ]; then unknown=$arg; fi ;;
    *) filter="$arg" ;;
  esac
done
# --help wins over every other argument, a mistyped option included.
if [ "$help" = 1 ]; then
  cmd_path=$name
  if [ "$(basename "$(dirname "$(pwd)")")" = "agent_plans" ]; then cmd_path="agent_plans/$name"; fi
  for key in status.usage status.helpFilter status.helpAll status.helpOptions status.helpJson; do
    msg "$key" "$cmd_path"
  done
  exit 0
fi
if [ -n "$unknown" ]; then
  msg status.unknownOption "$unknown" >&2
  exit 1
fi

# Autopilot log: the latest notes/run-*.md; open while it has no "## Closing".
# Sorted by date and then by the numeric suffix (no suffix = 1, then -2, -3, … -10).
# Date and suffix come from the base name by the pattern run-YYYY-MM-DD[-N].md; any other name is not a log.
# shellcheck disable=SC2012 # awk drops every name outside the pattern above, which has no spaces
run_log=$(ls -1 notes/run-*.md 2>/dev/null | awk '{ n = split($0, ps, "/"); b = ps[n]
  if (b !~ /^run-[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9](-[0-9]+)?\.md$/) next
  s = substr(b, 15); sub(/\.md$/, "", s); sub(/^-/, "", s)
  printf "%s %09d %s\n", substr(b, 5, 10), (s == "" ? 1 : s + 0), $0 }' | sort | tail -1 | cut -d" " -f3-)
run_log_open=0
if [ -n "$run_log" ] && ! grep -q '^## Closing' "$run_log"; then run_log_open=1; fi
# The run object, already JSON. handoff: the title of the log's last "## Handoff", without the separator;
# when it starts with YYYY-MM-DD HH:MM, only the timestamp; with none, null. It reaches the main awk through
# the environment (PR_RUN), because awk's -v would interpret the JSON backslashes.
run_obj=null
if [ -n "$run_log" ]; then
  run_obj=$(awk -v d="$run_log" -v open="$run_log_open" '
/^## Handoff([^A-Za-z0-9_]|$)/ { h = substr($0, 11); has = 1 }
END {
  sub(/^[ \t]+/, "", h); sub(/^(—|–|-)/, "", h); sub(/^[ \t]+/, "", h); sub(/[ \t\r]+$/, "", h)
  if (h ~ /^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9] [0-9][0-9]:[0-9][0-9]/ && substr(h, 17, 1) !~ /[0-9]/) h = substr(h, 1, 16)
  for (i = 1; i < 32; i++) esc[sprintf("%c", i)] = sprintf("\\u%04x", i)
  esc["\t"] = "\\t"; esc["\\"] = "\\\\"; esc["\""] = "\\\""
  r = ""
  for (i = 1; i <= length(h); i++) { c = substr(h, i, 1); r = r ((c in esc) ? esc[c] : c) }
  printf "{\"log\": \"%s\", \"open\": %s, \"handoff\": %s}", d, (open == 1 ? "true" : "false"), (has ? "\"" r "\"" : "null")
}' "$run_log")
fi

# Natural order: phases by the N of phase-N-<slug> (phase-2 before phase-10) and, within a phase,
# tasks by the value of each part of the ID (1-03 before 1-03.1 before 1-04; 1-9 before 1-10).
# One file per line: a task name may hold spaces (contract), never a line break.
# shellcheck disable=SC2012 # ls -1 gives one name per line, and awk keeps each line whole
files=$(ls -1 phase-*/F[0-9]*.md 2>/dev/null | awk -F/ '{
  f = $1; sub(/^phase-/, "", f); split(f, p, "-"); k = sprintf("%09d", p[1])
  if (match($2, /^F[0-9]+-[0-9]+(\.[0-9]+)*/)) {
    m = split(substr($2, 2, RLENGTH - 1), c, /[-.]/)
    for (i = 1; i <= m; i++) k = k "." sprintf("%09d", c[i])
  } else k = k "~" $2
  printf "%s\t%s\n", k, $0
}' | LC_ALL=C sort | cut -f2)
# Split only on line breaks and without globbing, so a space or a [ in a name stays in it.
old_ifs=$IFS
IFS='
'
set -f
# shellcheck disable=SC2086 # $files is split on purpose: one argument per task
set -- $files
set +f
IFS=$old_ifs
if [ "$#" -eq 0 ]; then
  if [ "$json" = 1 ]; then
    # the folder name and the plan.json fields may hold a quote or a backslash: escaped for JSON
    json_name=$(printf '%s' "$name" | sed 's/\\/\\\\/g; s/"/\\"/g')
    json_language=$(printf '%s' "$language" | sed 's/\\/\\\\/g; s/"/\\"/g')
    json_profile=$(printf '%s' "$profile" | sed 's/\\/\\\\/g; s/"/\\"/g')
    printf '{"contract": 1, "name": "%s", "language": "%s", "profile": "%s", "scripts_version": %s, "progress":{"done": 0, "total": 0, "pct": 0, "in_progress": 0, "draft": 0}, "phases": [], "tasks": [], "parallel": [], "run": %s}\n' "$json_name" "$json_language" "$json_profile" "$version" "$run_obj"
    exit 0
  fi
  msg status.noTasks "$name"
  exit 0
fi

# One awk pass reads every header; the only date call is the current time, so the processes this
# script starts do not grow with the number of tasks.
PR_RUN="$run_obj" awk -v name="$name" -v filter="$filter" -v all="$all" -v options="$options" -v json="$json" \
    -v language="$language" -v profile="$profile" -v version="$version" \
    -v now="$(date -u +%s)" "$MSG_AWK$HEADER_AWK"'
BEGIN {
  for (i = 1; i < 32; i++) esc[sprintf("%c", i)] = sprintf("\\u%04x", i)
  esc["\t"] = "\\t"; esc["\n"] = "\\n"; esc["\r"] = "\\r"; esc["\\"] = "\\\\"; esc["\""] = "\\\""
}
# id is the key of the file (see HEADER_AWK): the bare id, or "<ID>#<n>" for a second file with the same id.
FNR == 1 {
  id = hdr_begin()
  order[++total] = id
  file[id] = FILENAME
  phase[id] = hdr_phase
}
# The duration counts from the first Started: of the header; a value outside the contract form has none.
hdr_on && !(id in start_seen) && /^Started:/ { start_seen[id] = 1; v = $0; sub(/^Started:[ \t]*/, "", v); v = to_epoch(v); if (v != "") start[id] = v }
hdr_line(id) { next }
# Only a line that starts with "Next step:", after spaces and an optional "- "/"* "; a quote mid-text does not count.
/^[ \t]*([-*][ \t]+)?Next step:/ { has_next[id] = 1; v = $0; sub(/^[ \t]*([-*][ \t]+)?Next step:[ \t]*/, "", v); last_next[id] = v }
function matches(id) {
  if (filter == "") return 1
  if (index(hdr_idof(id), filter) == 1) return 1
  return track[id] == filter
}
function line(id, extra) {
  printf "  %-9s %-24s %s%s\n", hdr_idof(id), "[" type[id] "/" track[id] "]", title[id], extra
}
# How many live tasks cite the id of this key in Blocked by: (the copies of a duplicated id share it).
function unb(id) { return unblocks[hdr_idof(id)] + 0 }
function rep(id) { return repos[id] == "" ? "—" : repos[id] }
function is_owner(id) { return type[id] == "decision" || type[id] == "human" }
# Tier: junior, mid or senior; missing or any other value (case included) counts as senior.
function tier_of(id) { return (tier[id] == "junior" || tier[id] == "mid") ? tier[id] : "senior" }
# "2026-11-13T10:42Z" (UTC) in seconds since 1970, by the civil calendar; "" outside that form.
function to_epoch(v,   y, mo, d, h, mi, era, yoe, doy, doe) {
  sub(/[ \t\r]+$/, "", v)
  if (v !~ /^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]Z$/) return ""
  y = substr(v, 1, 4) + 0; mo = substr(v, 6, 2) + 0; d = substr(v, 9, 2) + 0
  h = substr(v, 12, 2) + 0; mi = substr(v, 15, 2) + 0
  if (y < 1 || mo < 1 || mo > 12 || d < 1 || d > 31 || h > 23 || mi > 59) return ""
  if (mo <= 2) y--
  era = int(y / 400); yoe = y - era * 400
  doy = int((153 * (mo > 2 ? mo - 3 : mo + 9) + 2) / 5) + d - 1
  doe = yoe * 365 + int(yoe / 4) - int(yoe / 100) + doy
  return (era * 146097 + doe - 719468) * 86400 + h * 3600 + mi * 60
}
function duration(s,   d, h, mi) {
  if (s < 0) s = 0
  d = int(s / 86400); h = int((s % 86400) / 3600); mi = int((s % 3600) / 60)
  if (d > 0) return msg("status.durationDH", d, h)
  if (h > 0) return msg("status.durationHMin", h, mi)
  return msg("status.durationMin", mi)
}
function collides(id,   m, rs, j) {
  if (repos[id] == "") return 0
  m = split(repos[id], rs, ",")
  for (j = 1; j <= m; j++) if (rs[j] in taken) return 1
  return 0
}
function occupy(id,   m, rs, j) {
  if (repos[id] == "") return
  m = split(repos[id], rs, ",")
  for (j = 1; j <= m; j++) taken[rs[j]] = id
}
# A quoted JSON string: backslash, quotes and control characters escaped, byte by byte.
function js(s,   r, i, c) {
  r = ""
  for (i = 1; i <= length(s); i++) { c = substr(s, i, 1); r = r ((c in esc) ? esc[c] : c) }
  return "\"" r "\""
}
function jsnull(s) { return s == "" ? "null" : js(s) }
# A list separated by commas (or by ", ") as a JSON array of strings.
function jsarr(list, sep,   m, xs, j, r) {
  r = ""
  m = split(list, xs, sep)
  for (j = 1; j <= m; j++) if (xs[j] != "") r = r (r == "" ? "" : ", ") js(xs[j])
  return "[" r "]"
}
function sort_by_unblocks(arr, n,   i, j, k) {
  for (i = 2; i <= n; i++) { k = arr[i]; j = i - 1; while (j >= 1 && unb(arr[j]) < unb(k)) { arr[j+1] = arr[j]; j-- } arr[j+1] = k }
}
END {
  # A duplicated id (more than one file): each file keeps its header, and the status it shows, but in
  # every count that reads the state it has none, so it is invalid, never done, and blocks who cites it.
  for (i = 1; i <= total; i++) {
    x = order[i]
    shown[x] = state[x]
    if (hdr_idof(x) in hdr_dup) { state[x] = ""; dup[++ndup] = x }
  }
  for (i = 1; i <= total; i++) {
    x = order[i]
    if (blockers[x] == "" || state[x] == "done" || state[x] == "cancelled" || state[x] == "abandoned") continue
    m = split(blockers[x], bs, ",")
    for (j = 1; j <= m; j++) if (bs[j] != "") unblocks[bs[j]]++
  }
  # Abandoned phase: every task in it (filtered or not) cancelled or abandoned, and at least one abandoned.
  for (i = 1; i <= total; i++) {
    x = order[i]; f = phase[x]
    if (state[x] == "abandoned") fabandoned[f] = 1
    else if (state[x] != "cancelled") falive[f] = 1
  }
  nprog = 0; navail = 0; nowner = 0; nwait = 0; ndone = 0; ncanc = 0; naban = 0; ndraft = 0; nfilt = 0; ninvalid = 0; nnonext = 0; nf = 0
  for (i = 1; i <= total; i++) {
    id = order[i]
    if (!matches(id)) continue
    nfilt++
    f = phase[id]
    # the phase enters once, at its first filtered task, even a cancelled one (ftot counts neither cancelled nor abandoned)
    if (!(f in seen)) { seen[f] = 1; phases[++nf] = f }
    if (state[id] != "cancelled" && state[id] != "abandoned") ftot[f]++
    if (state[id] == "done") fdone[f]++
    e = state[id]
    # A Tier: outside the three values counts as senior (tier_of); the text warns, --json does not change.
    if ((id in tier) && tier[id] != "junior" && tier[id] != "mid" && tier[id] != "senior" && type[id] != "human" && e != "cancelled" && e != "abandoned") tbad[++ntbad] = id
    if (e == "in-progress") { inprog[++nprog] = id; fprog[f]++; group[id] = "in-progress"; if (!(id in has_next)) nonext[++nnonext] = id; continue }
    if (e == "done") { done_ids[++ndone] = id; group[id] = "done"; continue }
    if (e == "cancelled") { canc[++ncanc] = id; group[id] = "cancelled"; continue }
    if (e == "abandoned") { aban[++naban] = id; group[id] = "abandoned"; continue }
    if (e == "draft") { drafts[++ndraft] = id; group[id] = "draft"; continue }
    if (e != "ready") { if (!(hdr_idof(id) in hdr_dup)) invalid[++ninvalid] = id; group[id] = "invalid"; continue }
    pending = ""
    if (blockers[id] != "") {
      m = split(blockers[id], bs, ",")
      for (j = 1; j <= m; j++) {
        b = bs[j]
        if (b == "") continue
        if (!(b in state)) { pending = pending (pending == "" ? "" : ", ") b "(?)"; continue }
        if (state[b] != "done") pending = pending (pending == "" ? "" : ", ") b
      }
    }
    if (pending == "") { if (is_owner(id)) { owners[++nowner] = id; group[id] = "owner" } else { avail[++navail] = id; group[id] = "available" } }
    else { waiting[++nwait] = id; waiting_on[id] = pending; group[id] = "blocked" }
  }
  sort_by_unblocks(avail, navail)
  sort_by_unblocks(owners, nowner)

  # parallel sessions: available tasks sharing no repo with each other or with those in progress
  for (i = 1; i <= nprog; i++) occupy(inprog[i])
  np = 0; ndef = 0
  for (i = 1; i <= navail; i++) {
    if (collides(avail[i])) { deferred[++ndef] = avail[i]; continue }
    occupy(avail[i]); par[++np] = avail[i]
  }

  if (options == 1) {
    for (i = 1; i <= navail; i++) printf "%s\tavailable\t%d\t%s\t%s\n", avail[i], unb(avail[i]), type[avail[i]], title[avail[i]]
    for (i = 1; i <= nowner; i++) printf "%s\towner\t%d\t%s\t%s\n", owners[i], unb(owners[i]), type[owners[i]], title[owners[i]]
    exit
  }

  ndone_total = ndone; counted = nfilt - ncanc - naban
  pct = counted > 0 ? int(100 * ndone_total / counted + 0.5) : 0

  if (json == 1) {
    printf "{\"contract\": 1, \"name\": %s, \"language\": %s, \"profile\": %s, \"scripts_version\": %s,\n", js(name), js(language), js(profile), version
    printf "\"progress\": {\"done\": %d, \"total\": %d, \"pct\": %d, \"in_progress\": %d, \"draft\": %d},\n", ndone_total, counted, pct, nprog, ndraft
    printf "\"phases\": ["
    for (i = 1; i <= nf; i++) {
      f = phases[i]; tf = f; phase_file = f "/PHASE.md"
      while ((getline lf < phase_file) > 0) if (lf ~ /^# /) { tf = substr(lf, 3); sub(/\r$/, "", tf); break }
      close(phase_file)
      printf "%s\n  {\"dir\": %s, \"title\": %s, \"done\": %d, \"total\": %d, \"in_progress\": %d%s}", (i > 1 ? "," : ""), js(f), js(tf), fdone[f] + 0, ftot[f] + 0, fprog[f] + 0, ((f in fabandoned) && !(f in falive) ? ", \"abandoned\": true" : "")
    }
    printf "],\n\"tasks\": ["
    k = 0
    for (i = 1; i <= total; i++) {
      x = order[i]
      if (!matches(x)) continue
      printf "%s\n  {\"id\": %s, \"title\": %s, \"status\": %s, \"type\": %s, \"track\": %s, \"tier\": %s, ", (k++ > 0 ? "," : ""), js(hdr_idof(x)), js(title[x]), js(shown[x]), js(type[x]), js(track[x]), js(tier_of(x))
      printf "\"repos\": %s, \"blocked_by\": %s, \"waiting_on\": %s, ", jsarr(repos[x], ","), jsarr(blockers[x], ","), jsarr(waiting_on[x], ", ")
      printf "\"group\": %s, \"unblocks\": %d, \"started\": %s, \"finished\": %s, ", js(group[x]), unb(x), jsnull(started[x]), jsnull(finished[x])
      printf "\"next_step\": %s, ", ((x in last_next) ? js(last_next[x]) : "null")
      # the give-up and replacement keys exist only when the header has them, with a value
      if (replaced[x] != "") printf "\"replaced_by\": %s, ", js(replaced[x])
      if (gave_up[x] != "") printf "\"given_up_by\": %s, ", js(gave_up[x])
      if (fell_with[x] != "") printf "\"given_up_with\": %s, ", js(fell_with[x])
      printf "\"file\": %s}", js(file[x])
    }
    printf "],\n\"parallel\": ["
    for (i = 1; i <= np; i++) printf "%s%s", (i > 1 ? ", " : ""), js(par[i])
    printf "],\n\"run\": %s}\n", ENVIRON["PR_RUN"]
    exit
  }
  print msg("status.progress", ndone_total, counted, pct, nprog, ndraft)
  for (i = 1; i <= nf; i++) {
    f = phases[i]
    bar = ""; w = 20; filled = ftot[f] > 0 ? int(w * fdone[f] / ftot[f] + 0.5) : 0
    for (j = 1; j <= w; j++) bar = bar (j <= filled ? "#" : ".")
    printf "  %-26s [%s] %d/%d%s%s\n", f, bar, fdone[f] + 0, ftot[f], (fprog[f] > 0 ? "  " msg("status.phaseInProgress", fprog[f]) : ""), ((f in fabandoned) && !(f in falive) ? "  " msg("status.phaseAbandoned") : "")
  }
  print ""
  print msg("status.inProgress", nprog)
  for (i = 1; i <= nprog; i++) {
    x = inprog[i]
    line(x, "  · " ((x in start) ? msg("status.ago", duration(now - start[x]), started[x]) : msg("status.noStarted")))
    if (x in last_next) print "            " msg("status.nextStep", last_next[x])
  }
  print ""
  print msg("status.available", navail)
  for (i = 1; i <= navail; i++) line(avail[i], "  · " msg("status.reposUnblocks", rep(avail[i]), unb(avail[i])))
  print ""
  print msg("status.owner", nowner)
  for (i = 1; i <= nowner; i++) line(owners[i], "  · " msg("status.unblocks", unb(owners[i])))
  if (navail > 0) {
    print ""
    print msg("status.parallel")
    for (i = 1; i <= np; i++) print "  " msg("status.session", i, par[i])
    for (i = 1; i <= ndef; i++) print "  " msg("status.later", deferred[i], rep(deferred[i]))
  }
  print ""
  print msg("status.waiting", nwait)
  for (i = 1; i <= nwait; i++) line(waiting[i], "  " msg("status.waitsOn", waiting_on[waiting[i]]))
  if (nnonext > 0) {
    print ""
    print msg("status.noNextStep", nnonext)
    for (i = 1; i <= nnonext; i++) printf "  %-9s %s\n", hdr_idof(nonext[i]), file[nonext[i]]
  }
  if (ntbad > 0) {
    print ""
    print msg("status.unknownTier", ntbad)
    for (i = 1; i <= ntbad; i++) printf "  %-9s Tier: %s  %s\n", hdr_idof(tbad[i]), tier[tbad[i]], file[tbad[i]]
  }
  if (ninvalid > 0) {
    print ""
    print msg("status.invalidStatus", ninvalid)
    for (i = 1; i <= ninvalid; i++) printf "  %-9s %s\n", invalid[i], file[invalid[i]]
  }
  # The files of each duplicated id, filter or not: renaming them is the way out.
  if (ndup > 0) {
    print ""
    print msg("status.duplicateId", ndup)
    for (i = 1; i <= ndup; i++) printf "  %-9s %s\n", hdr_idof(dup[i]), file[dup[i]]
  }
  if (all == 1) {
    print ""
    print msg("status.drafts", ndraft)
    for (i = 1; i <= ndraft; i++) line(drafts[i], "")
    print ""
    print msg("status.done", ndone)
    for (i = 1; i <= ndone; i++) line(done_ids[i], "")
    print ""
    print msg("status.cancelled", ncanc)
    for (i = 1; i <= ncanc; i++) line(canc[i], "")
    print ""
    print msg("status.abandoned", naban)
    for (i = 1; i <= naban; i++) line(aban[i], "")
  }
  print ""
  print msg("status.legend")
}
' "$@"
